<?php session_start(); include 'db.php'; // Only allow admin if (!isset($_SESSION['role']) || $_SESSION['role'] !== 'admin') { header("Location: login.html"); exit(); } // Update payment status if requested if (isset($_GET['mark_paid'])) { $booking_id = intval($_GET['mark_paid']); $stmt = $conn->prepare("UPDATE bookings SET payment_status='paid' WHERE booking_id=?"); $stmt->bind_param("i", $booking_id); $stmt->execute(); header("Location: payments.php"); // reload page exit(); } // Fetch all bookings with user and tour details $sql = "SELECT b.booking_id, u.full_name, u.email, t.tour_name, b.tour_date, b.payment_status FROM bookings b JOIN users u ON b.user_id = u.id JOIN tours t ON b.tour_id = t.tour_id ORDER BY b.booking_id DESC"; $result = $conn->query($sql); ?> <!DOCTYPE html> <html lang="en"> <head> <meta charset="UTF-8"> <title>Payments - Admin Dashboard</title> <style> body { font-family: Arial, sans-serif; background: #f0f3f7; padding: 30px; } h2 { text-align: center; margin-bottom: 20px; } table { width: 100%; border-collapse: collapse; background: #fff; } th, td { padding: 12px; border: 1px solid #ccc; text-align: center; } th { background: #6b8e23; color: white; } a { text-decoration: none; color: #007bff; } a:hover { text-decoration: underline; } button { padding: 5px 10px; border: none; border-radius: 5px; cursor: pointer; } .paid { background: #28a745; color: white; } .pending { background: #ffc107; color: black; } </style> </head> <body> <h2>Payments</h2> <table> <tr> <th>Booking ID</th> <th>User</th> <th>Email</th> <th>Tour</th> <th>Tour Date</th> <th>Payment Status</th> <th>Action</th> </tr> <?php if ($result->num_rows > 0) { while ($row = $result->fetch_assoc()) { echo "<tr> <td>".$row['booking_id']."</td> <td>".$row['full_name']."</td> <td>".$row['email']."</td> <td>".$row['tour_name']."</td> <td>".$row['tour_date']."</td> <td>".$row['payment_status']."</td> <td>"; if ($row['payment_status'] == 'pending') { echo "<a href='payments.php?mark_paid=".$row['booking_id']."'><button class='pending'>Mark as Paid</button></a>"; } else { echo "<button class='paid' disabled>Paid</button>"; } echo "</td></tr>"; } } else { echo "<tr><td colspan='7'>No bookings found</td></tr>"; } ?> </table> <p style="text-align:center; margin-top:15px;"><a href="admin_dashboard.php" style="text-decoration:none; color:#6b8e23;">Back to Dashboard</a></p> </body> </html>
        ?>
